def test_monitor_flag_rate_none_counts_as_unflagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": False}] * 3, "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == pooled_flag_rate({"empty": []}) == 0.0


@pytest.mark.parametrize(("days", "expected"), [(0, 0), (2, 5), (5, 6)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 3], days) == expected


def test_parse_transcript_log_skips_lines_and_trims_fields():
    lines = ["\n", " \t\n", "  # ignored", " a , 2 , 1 ", " b , 3 , 0 ", " c , 4 ,  "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 2, "flagged": True},
        {"id": "b", "day": 3, "flagged": False},
        {"id": "c", "day": 4, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,1"])
def test_parse_transcript_log_error_counts_skipped_lines(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["", "  # ignored", "a,1,0", bad_line])


def test_dedupe_transcripts_keeps_last_record_and_sorts():
    events = parse_transcript_log(["a,5,1", "c,3,1", "b,2,1", "a,2,0"])
    assert dedupe_transcripts(events) == [events[3], events[2], events[1]]


def test_daily_flag_counts_includes_boundaries_and_empty_days():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,2,", "f,3,1", "g,4,1"])
    assert daily_flag_counts(events, 1, 3) == [2, 0, 1]
    assert daily_flag_counts(events, 3, 1) == []


def test_monitor_summary_uses_calendar_days_and_nonempty_groups():
    groups = {
        "a": parse_transcript_log(["a,1,1", "b,3,1"]),
        "b": parse_transcript_log(["c,5,0"]),
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 3)["recent"] == 1
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [{"flagged": True}], "b": [{"flagged": False}],
              "a": [{"flagged": True}], "empty": []}
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 5) == ["a", "z", "b"]


def test_flag_rate_by_group_sorts_keys_and_maps_empty_groups_to_none():
    groups = {"z": [], "b": [{"flagged": True}], "a": [{"flagged": None}]}
    assert list(flag_rate_by_group(groups).items()) == [("a", 0.0), ("b", 1.0), ("z", None)]


@pytest.mark.parametrize(("counts", "expected"), [([], 0), ([0, -1], 0), ([1, 0, 2, 3, -1, 4, 0, 5], 2)])
def test_longest_flag_streak(counts, expected):
